      "facial_hair": "修剪整齐的胡须和八字胡。",
      "eyewear": "{argument name="eyewear" default="时尚的粗黑框眼镜。"}",
      "clothing": "{argument name="clothing" default="深黑色罗纹高领毛衣。"}",
      "accessories": {
        "ring": "手指上佩戴一枚精致优雅的奢华戒指。",
        "watch": "手腕上佩戴一块高级抛光银色金属腕表，表盘为深色，清晰可见。"
